from collections import deque

def shortest_path(graph, source, target):
    if source == target:
        return (0, [source])

    # Initialize the distance and path dictionaries
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    paths = {node: [] for node in graph}
    paths[source] = [source]

    # Initialize the queue for BFS
    queue = deque([(source, 0)])

    while queue:
        current_node, current_distance = queue.popleft()

        if current_node == target:
            return (current_distance, paths[target])

        for neighbor, weight in graph[current_node]:
            if current_distance + weight < distances[neighbor]:
                distances[neighbor] = current_distance + weight
                paths[neighbor] = paths[current_node] + [neighbor]
                queue.append((neighbor, distances[neighbor]))

    # If we reach here, target is not reachable from source
    return (float('inf'), None)

