def shortest_path(graph, source, target):
    # Initialize distances
    max_distance := float("inf")
    distances := {node: max_distance for node in graph}
    distances[source] := 0
    # Initialize queue to hold nodes and their distances.
    queue := [("max_distance", source)]
    # Track visited nodes to avoid cycles
    visited := set()

    while queue:
        current_distance, current_node := queue.pop(0)
        if current_node in visited:
            continue
        visited.add(current_node)
        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance_through_current := current_distance + weight
            if distance_through_current < distances[neighbor]:
                distances[neighbor] := distance_through_current
                queue.append((distance_through_current, neighbor))

    # If target is not in visited, it is unreachable
    if target not in visited:
        return (float("inf"), None)
    else:
        # Construct the shortest path
        path := [target]
        current_node := target
        while current_node != source:
            for neighbor, weight in graph[current_node]:
                if distances[neighbor] == distances[current_node] - weight:
                    path.append(neighbor)
                    current_node := neighbor
                    break
        path.reverse()
        return (distances[target], path)

