    # Check if the neighbor is not in the graph, return infinity and None as unreachable
    if target not in graph:
        return float("inf"), None

    # Initialize variables
    distance = float("inf")
    path = []
    visited = set()
    queue = [(source, [source])]

    while queue:
        (node, path) = queue.pop(0)
        if node == target:
            if distance > len(path) - 1:
                distance = len(path) - 1
                path = path[:-1]

        if node in visited:
