        visited.add(node)

        # Get neighbors and their distances from the graph
        for (neighbor, weight) in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))

    # If path is still an empty list, the target is unreachable
    if not path:
        return float("inf"), None
    else:
