def shortest_path(graph, source, target):
    # Initialize distances and paths with infinity and None
    distances = {node: float('inf') for node in graph}
    paths = {node: None for node in graph}
    distances[source] = 0

    # Priority queue to manage unvisited nodes
    from heapq import heappush, heappop
    priority_queue = [(0, source)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # Skip if the current node is not the target and we have already found a shorter path
        if current_node == target and current_distance < distances[target]:
            return (current_distance, paths[target])

        # If we have already found a shorter path to the current node, skip
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a shorter path is found to the neighbor
            if distance < distances[neighbor]:
                paths[neighbor] = [current_node, neighbor]
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    # If we have exhausted the priority queue without finding the target, it's unreachable
    return (float('inf'), None)

