    # Initialize the path and distance dictionaries
    path = {source: []}
    distance = {source: 0}

    # Helper function to perform DFS
    def dfs(node, node_path, node_distance):
        if node == target:
            return node_path, node_distance

        for neighbor, weight in graph[node]:
            if neighbor not in node_path:
                new_path = node_path + [neighbor]
                new_distance = node_distance + weight
                if neighbor not in distance or new_distance < distance[neighbor]:
