                    distance[neighbor] = new_distance
                    new_path, new_distance = dfs(neighbor, new_path, new_distance)
                    if new_path is not None:
                        return new_path, new_distance
        return None, float("inf")

    # Start DFS from the source
    return dfs(source, [source], 0)

