from heapq import heappop, heappush

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return float("inf"), None

    # Initialize the distance dictionary and the priority queue
    distance = {node: float("inf") for node in graph}
    distance[source] = 0
    priority_queue = [(0, source)]

    # The path dictionary to reconstruct the path
    path = {source: []}

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        if current_node == target:
            # Found the target node, return the distance and reconstruct the path
            path[target] = [current_node]
            while current_node != source:
                for neighbor, weight in graph[path[current_node][-1]]:
                    if (current_distance - weight, neighbor) == path[path[current_node][-1]][-1]:
                        path[target].insert(0, neighbor)
                        break
            return (current_distance, path[target])

        for neighbor, weight in graph[current_node]:
            distance_sum = current_distance + weight
            if distance_sum < distance[neighbor]:
                distance[neighbor] = distance_sum
                path[neighbor] = path[current_node] + [neighbor]
                heappush(priority_queue, (distance_sum, neighbor))

    # Target is unreachable
    return float("inf"), None

