from collections import deque

def shortest_path(graph, source, target):
    # Check if the source and target are the same node
    if source == target:
        return (0, [source])

    # Initialize distances and previous nodes
    distances = {node: float("inf") for node in graph}
    previous_nodes = {node: None for node in graph}

    # Initialize the queue with (distance, node, path)
    queue = deque([(0, source, [source])])

    while queue:
        current_distance, current_node, current_path = queue.popleft()

        # If we reach the target node, return the path and distance
        if current_node == target:
            return (current_distance, current_path)

        # Explore neighbors
